// Window (Reminders v1): which reminder this is, and the days it covers (Manila).
// LAUNCH SWITCH: YEAR_SHIFT 1 during QA (bookings are a year ahead), 0 at launch - with main's Gate Context and Slack Interactions'.
const YEAR_SHIFT = 1;
let kind = 'daily'; try { const m = $('Monday 9 AM').first(); kind = (m && m.json) ? 'weekly' : 'daily'; } catch (e) { kind = 'daily'; }   // the Monday trigger ran -> weekly
const add = (d, n) => new Date(Date.parse(d + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10);
const today0 = new Date(Date.now() + 8 * 3600000).toISOString().slice(0, 10);
const today = (Number(today0.slice(0, 4)) + YEAR_SHIFT) + today0.slice(4);
let start, end;
if (kind === 'daily') { start = add(today, 1); end = add(start, 1); }
else { const dow = new Date(today + 'T12:00:00Z').getUTCDay(); start = add(today, -((dow + 6) % 7)); end = add(start, 7); }
return [{ json: { kind, start, end, timeMin: start + 'T00:00:00+08:00', timeMax: end + 'T00:00:00+08:00', yearShift: YEAR_SHIFT } }];

// The newest valid row of the Jessie Reference Cache data table (same check as main's Reference Snapshot).
function readCache(rows) {
  let best = null;
  for (const r of rows || []) {
    if (!r || r.cache_key !== 'jessie-reference') continue;
    let d; try { d = JSON.parse(r.payload); } catch (e) { continue; }
    if (!d || !Array.isArray(d.rooms) || !Array.isArray(d.sessionTypes) || !Array.isArray(d.bookers)) continue;
    const at = Date.parse(r.refreshed_at || '') || 0;
    if (!best || at > best.at) best = { at, d };
  }
  return best ? best.d : null;
}

// Booking rows (v11): a booking in a message is a section (block_id bk_<id>) and its Change / Cancel buttons (bka_<id>).
// The buttons carry the booking: {id, d: YYYY-MM-DD, s / e: HH:MM (Manila), r: room, t: title}.
const _DS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'], _MS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const _DL = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'], _ML = ['January','February','March','April','May','June','July','August','September','October','November','December'];
function t12(hm) { if (!hm) return ''; let [h, m] = String(hm).split(':').map(Number); const ap = h >= 12 ? 'PM' : 'AM'; h = h % 12 || 12; return h + ':' + String(m).padStart(2, '0') + ' ' + ap; }
function dayShort(d) { const x = new Date(d + 'T12:00:00Z'); return _DS[x.getUTCDay()] + ', ' + _MS[x.getUTCMonth()] + ' ' + x.getUTCDate(); }
function dayLong(d) { const x = new Date(d + 'T12:00:00Z'); return _DL[x.getUTCDay()] + ', ' + _ML[x.getUTCMonth()] + ' ' + x.getUTCDate() + ', ' + x.getUTCFullYear(); }
function addDays(d, n) { return new Date(Date.parse(d + 'T12:00:00Z') + n * 86400000).toISOString().slice(0, 10); }
function whenLine(b) { return dayShort(b.d) + ' · ' + (b.s && !(b.s === '00:00' && b.e === '00:00') ? t12(b.s) + ' – ' + t12(b.e) : 'all day') + (b.r ? ' · ' + roomMain(b.r) + (roomHold(b.r) ? ' + ' + roomHold(b.r) : '') : ''); }
function bkValue(b) { return JSON.stringify({ id: b.id, d: b.d, s: b.s || '', e: b.e || '', r: b.r || '', t: String(b.t || '').slice(0, 150), st: b.st || '' }); }   // v24: st
function bkButtons(b) {
  const pt = x => ({ type: 'plain_text', text: x });
  return { type: 'actions', block_id: 'bka_' + b.id, elements: [
    { type: 'button', action_id: 'bk_change', value: bkValue(b), text: pt('Change') },
    { type: 'button', action_id: 'bk_cancel', style: 'danger', value: bkValue(b), text: pt('Cancel'),
      confirm: { title: pt('Cancel this booking?'), text: { type: 'mrkdwn', text: ('*' + b.t + '*\n' + whenLine(b)).slice(0, 290) },
                 confirm: pt('Cancel booking'), deny: pt('Keep it'), style: 'danger' } } ] };
}
// v21: a booking's rooms - the first is the studio, a later studio / M booth is its booth ("Studio F + Studio A"),
// any other later room is a holding room
function roomList(r) { return String(r || '').split(',').map(x => x.trim()).filter(Boolean); }
function roomMain(r) { const a = roomList(r); return [a[0]].concat(a.slice(1).filter(x => /^(?:Studio\s|M\d)/i.test(x))).filter(Boolean).join(' + '); }
function roomHold(r) { return roomList(r).slice(1).filter(x => !/^(?:Studio\s|M\d)/i.test(x)).join(', '); }
function roomExtras(r) { return roomList(r).slice(1); }
function bkCard(b, head) { return head + '\n\n*' + b.t + '*\n*Date:* ' + dayLong(b.d) + '\n*Time:* ' + (b.s && !(b.s === '00:00' && b.e === '00:00') ? t12(b.s) + ' – ' + t12(b.e) : 'All day') + '\n*Room:* ' + (roomMain(b.r) || '-') + (roomHold(b.r) ? '\n*Holding room:* ' + roomHold(b.r) : ''); }
// a Google event -> a booking (Manila times; the room from its room attendee, else its location)
// v19: a calendar room label ("KDC Plaza-Top Level-Likha (Big Room)") -> the room's own name ("Likha")
function roomName(x) { return String(x || '').replace(/^KDC Plaza-Top Level-/i, '').replace(/(?:\s*\([^)]*\))+\s*$/, '').trim(); }   // v22: "Likha (Big Room) (12)" -> Likha
function evRoom(e) { const r = (e.attendees || []).filter(a => a.resource || /@resource\.calendar\.google\.com$/i.test(String(a.email || '')))
  .map(a => roomName(a.displayName)).filter(Boolean);
  // v22: Google lists the rooms in its own order - the booking's "Rooms:" line keeps studio, booth, holding rooms
  const w = (String(e.description || '').match(/(?:^|\|)\s*Rooms:\s*([^|\n]+)/i) || [])[1];
  if (w && r.length) { const o = w.split(',').map(x => x.trim()).filter(Boolean), lc = a => a.map(x => x.toLowerCase()).sort().join();
    if (lc(o) === lc(r)) return r.slice().sort((x, y) => o.findIndex(z => z.toLowerCase() === x.toLowerCase()) - o.findIndex(z => z.toLowerCase() === y.toLowerCase())).join(', '); }
  return r.length ? r.join(', ') : roomName(e.location); }
function evType(e) { return ((String(e.description || '').match(/\n\s*SType:\s*([^\n]+)/) || [])[1] || '').trim(); }   // v24
function evBooking(e) {
  const sd = e.start && e.start.dateTime, ed = e.end && e.end.dateTime;
  const m = x => { const d = new Date(new Date(x).getTime() + 8 * 3600000); return { d: d.toISOString().slice(0, 10), hm: d.toISOString().slice(11, 16) }; };
  if (sd) { const a = m(sd), b = m(ed); return { id: e.id, d: a.d, s: a.hm, e: b.hm, r: evRoom(e), t: e.summary || '(no title)', st: evType(e) }; }
  return { id: e.id, d: String((e.start && e.start.date) || ''), s: '', e: '', r: evRoom(e), t: e.summary || '(no title)', st: evType(e) };
}


// ---- Build Reminders (v1, 20 Oct): one DM per person - tomorrow's studio sessions (daily) or the week's bookings (Monday)
// LAUNCH SWITCH: DEV_REDIRECT '' at launch. During QA a reminder goes to its person only when on ALLOW, else to DEV_REDIRECT.
const DEV_REDIRECT = 'U08V3CKDGJF';
// v2 (Howard, 20 Oct): during QA every reminder goes to DEV_REDIRECT, ALLOW included (inert once DEV_REDIRECT is '')
const ALL_TO_DEV = true;
const ALLOW = ['U08V3CKDGJF','U098UFMKQHZ','U08JL17A50A','U0B4S0EKSAY','U098UFLG70B','U026N6E1R','U045A3VQER3'];
const W = $('Window').first().json;
const res = $('List Events R').first().json || {};
const items = Array.isArray(res.items) ? res.items : null;
if (!items) return [];   // the calendar could not be read - nothing sent, never a wrong reminder
const data = readCache($('Read Cache R').all().map(i => i.json || {})) || { bookers: [], rooms: [] };
const staff = (data.bookers || []).map(b => b.fields || {}).filter(f => f.Name);
const idOf = f => String(f['Slack User ID'] || '').split(/[\s,]+/).filter(Boolean)[0] || '';
const byName = n => { const q = String(n || '').trim().toLowerCase(); if (!q) return '';
  const h = staff.filter(f => { const full = String(f.Name).trim().toLowerCase(), fst = full.split(/\s+/)[0];
    const al = ((String(f.Info || '').match(/goes by\s+([^\n]*)/i) || [])[1] || '').split(/,|\band\b/).map(x => x.trim().replace(/\.$/, '').toLowerCase()).filter(Boolean);
    return q === full || q === fst || al.indexOf(q) !== -1; });
  return h.length === 1 ? idOf(h[0]) : ''; };
const nameOf = id => { const f = staff.find(x => idOf(x) === id); return f ? String(f.Name).trim() : ''; };
const roomRec = n => (data.rooms || []).map(r => r.fields || {}).find(f => String(f['Room Name'] || '').trim().toLowerCase() === String(n || '').trim().toLowerCase()) || {};
const kindOf = n => { if (/^M\d+$/i.test(String(n || '').trim())) return 'booth';
  const t = [].concat(roomRec(n)['Room Type'] || []).map(x => String((x && x.name) || x).toLowerCase());
  return t.some(x => /conference|lobby/.test(x)) ? 'common' : 'studio'; };
const per = {};
for (const e of items) {
  if (!e || e.status === 'cancelled') continue;
  const desc = String(e.description || '');
  const ref = (desc.match(/ref:\s*([A-Za-z0-9]+)/) || [])[1] || '';
  if (!ref) continue;   // only bookings made through Jessie
  const b = evBooking(e);
  if (W.kind === 'daily' && (kindOf(roomList(b.r)[0] || '') !== 'studio' || b.d !== W.start)) continue;
  const team = ((desc.match(/team:\s*([^|]+)/) || [])[1] || '').split(/[\s,]+/).filter(x => /^U[A-Z0-9]+$/.test(x));
  const named = [(desc.match(/Engineer:\s*([^(|]+)/) || [])[1], (desc.match(/Arranger:\s*([^(|]+)/) || [])[1],
    (desc.match(/\(for\s+([^)]+)\)/i) || [])[1], (desc.match(/(?:^|\|)\s*For:\s*([^|]+)/) || [])[1]].map(byName).filter(Boolean);
  for (const id of [...new Set([ref].concat(team, named))]) { per[id] = per[id] || {}; per[id][b.id] = b; }
}
const md = t => ({ type: 'mrkdwn', text: t });
const pt = t => ({ type: 'plain_text', text: t });
const out = [];
for (const id of Object.keys(per)) {
  const rows = Object.values(per[id]).sort((x, y) => (x.d + (x.s || '00:00')).localeCompare(y.d + (y.s || '00:00')));
  const to = DEV_REDIRECT && (ALL_TO_DEV || ALLOW.indexOf(id) === -1) ? DEV_REDIRECT : id;
  const blocks = [];
  if (to !== id) blocks.push({ type: 'context', elements: [md('_Test: this reminder is for ' + (nameOf(id) || id) + '._')] });
  blocks.push({ type: 'section', text: md(W.kind === 'daily'
    ? '📅 *Tomorrow* · ' + dayLong(W.start) + '\nStill on? If plans changed, free up the room so someone else can book it.'
    : '📅 *Your week* · ' + dayShort(W.start) + ' – ' + dayShort(addDays(W.end, -1)) + '\nStill need these? Free up anything you won’t use.') });
  for (const b of rows.slice(0, 20)) {
    blocks.push({ type: 'section', block_id: 'bk_' + b.id, text: md('*' + b.t + '*\n' + whenLine(b)) });
    blocks.push({ type: 'actions', block_id: 'bka_' + b.id, elements: [
      { type: 'button', style: 'primary', action_id: 'rm_keep', value: JSON.stringify({ id: b.id, w: W.kind }), text: pt(W.kind === 'daily' ? 'Still on' : 'Keep') },
      { type: 'button', action_id: 'bk_change', value: bkValue(b), text: pt('Change') },
      { type: 'button', action_id: 'bk_cancel', style: 'danger', value: bkValue(b), text: pt('Free up the room'),
        confirm: { title: pt('Free up this room?'), text: md(('*' + b.t + '*\n' + whenLine(b)).slice(0, 290)), confirm: pt('Free it up'), deny: pt('Keep it'), style: 'danger' } }] });
  }
  if (rows.length > 20) blocks.push({ type: 'context', elements: [md('And ' + (rows.length - 20) + ' more - see *My bookings*.')] });
  blocks.push({ type: 'actions', block_id: 'rm_nav', elements: [{ type: 'button', action_id: 'my_bookings', value: 'menu', text: pt('My bookings') }] });
  const n = rows.length;
  out.push({ json: { channel: to, person: id, text: (W.kind === 'daily' ? 'Tomorrow: ' : 'Your week: ') + n + ' booking' + (n === 1 ? '' : 's') + ' - still on?', blocks } });
}
return out;
